select month(shipped_date) as shipped_month, concat_ws(', ', sort_array(collect_set(carrier))) as carrier_values, round((100 * sum(case when carrier = 'Kerry' then 1 else 0 end)) / count(*), 1) as pct_kerry, sum(case when carrier = 'DHL' then 1 else 0 end) as dhl_count from shipments where delivered_date between '2024-03-01' and '2025-10-25' and delivered_date <= '2023-11-01' group by shipped_month order by shipped_month desc, pct_kerry desc limit 5;
